import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import './CrearProducto.css';

export default function CrearProducto() {
  const [form, setForm] = useState({
    nombre: '',
    descripcion: '',
    precio: '',
    stock: '',
    id_categoria: '',
    imagen: ''
  });
  
  const [categorias, setCategorias] = useState([]);
  const [msg, setMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  // Cargar categorías al montar el componente
  useEffect(() => {
    cargarCategorias();
  }, []);

  const cargarCategorias = async () => {
    try {
      const response = await axios.get('http://localhost:3000/api/productos/categorias');
      setCategorias(response.data);
    } catch (err) {
      console.error('Error al cargar categorías:', err);
      setMsg('Error al cargar las categorías. Inténtalo de nuevo.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = e => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    setIsSubmitting(true);
    
    try {
      // Validaciones básicas
      if (!form.nombre || !form.descripcion || !form.precio || !form.stock || !form.id_categoria) {
        setMsg('Por favor, completa todos los campos obligatorios.');
        return;
      }

      if (form.precio <= 0) {
        setMsg('El precio debe ser mayor a 0.');
        return;
      }

      if (form.stock < 0) {
        setMsg('El stock no puede ser negativo.');
        return;
      }

      // Por ahora, usamos un id_artesano fijo (después se obtendrá del token)
      const datosProducto = {
        ...form,
        id_artesano: 1, // Esto debería venir del token de autenticación
        precio: parseFloat(form.precio),
        stock: parseInt(form.stock)
      };

      console.log('Enviando datos del producto:', datosProducto);
      
      const response = await axios.post('http://localhost:3000/api/productos', datosProducto);
      
      setMsg('¡Producto creado exitosamente!');
      
      // Limpiar formulario
      setForm({
        nombre: '',
        descripcion: '',
        precio: '',
        stock: '',
        id_categoria: '',
        imagen: ''
      });
      
      // Redirigir al dashboard después de 2 segundos
      setTimeout(() => {
        navigate('/dashboard-artesano');
      }, 2000);
      
    } catch (err) {
      console.error('Error al crear producto:', err);
      setMsg(err.response?.data?.msg || 'Error al crear el producto. Inténtalo de nuevo.');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="crear-producto-container">
        <div className="crear-producto-card">
          <h1 className="crear-producto-title">Cargando...</h1>
        </div>
      </div>
    );
  }

  return (
    <div className="crear-producto-container">
      <div className="crear-producto-card">
        <h1 className="crear-producto-title">Crear Nuevo Producto</h1>
        <p className="crear-producto-subtitle">Añade un nuevo producto a tu catálogo artesanal</p>
        
        <form onSubmit={handleSubmit} className="crear-producto-form">
          <div className="form-group">
            <label htmlFor="nombre">Nombre del Producto *</label>
            <div className="input-with-icon">
              <span className="input-icon">🏷️</span>
              <input
                id="nombre"
                name="nombre"
                type="text"
                placeholder="Ej: Pulsera de plata con detalles"
                value={form.nombre}
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="descripcion">Descripción *</label>
            <div className="input-with-icon">
              <span className="input-icon">📝</span>
              <textarea
                id="descripcion"
                name="descripcion"
                placeholder="Describe tu producto, materiales, técnicas utilizadas..."
                value={form.descripcion}
                onChange={handleChange}
                rows="4"
                required
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label htmlFor="precio">Precio (COP) *</label>
              <div className="input-with-icon">
                <span className="input-icon">💰</span>
                <input
                  id="precio"
                  name="precio"
                  type="number"
                  placeholder="0"
                  value={form.precio}
                  onChange={handleChange}
                  min="0"
                  step="0.01"
                  required
                />
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="stock">Stock Disponible *</label>
              <div className="input-with-icon">
                <span className="input-icon">📦</span>
                <input
                  id="stock"
                  name="stock"
                  type="number"
                  placeholder="0"
                  value={form.stock}
                  onChange={handleChange}
                  min="0"
                  required
                />
              </div>
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="id_categoria">Categoría *</label>
            <div className="input-with-icon">
              <span className="input-icon">🏷️</span>
              <select
                id="id_categoria"
                name="id_categoria"
                value={form.id_categoria}
                onChange={handleChange}
                required
              >
                <option value="">Selecciona una categoría</option>
                {categorias.map(categoria => (
                  <option key={categoria.id_categoria} value={categoria.id_categoria}>
                    {categoria.nombre}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="imagen">URL de la Imagen</label>
            <div className="input-with-icon">
              <span className="input-icon">🖼️</span>
              <input
                id="imagen"
                name="imagen"
                type="url"
                placeholder="https://ejemplo.com/imagen.jpg"
                value={form.imagen}
                onChange={handleChange}
              />
            </div>
            <small className="form-help">Pega la URL de la imagen de tu producto</small>
          </div>

          <div className="form-actions">
            <Link to="/dashboard-artesano" className="cancel-btn">
              Cancelar
            </Link>
            <button 
              type="submit" 
              className="crear-producto-btn"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Creando...' : 'Crear Producto'}
            </button>
          </div>
        </form>

        {msg && <div className="crear-producto-msg">{msg}</div>}
      </div>
    </div>
  );
}
